"                                                <button 
                                                     onClick={async () => {
                                                        if (confirm(`Are you sure you want to delete ${c.name || c.phone}?`)) {
                                                           try {
                                                              const res = await posService.deleteCustomer(c.phone);
                                                              if (res.data && res.data.success) {
                                                                 setCustomerDb(prev => {
                                                                     const next = { ...prev };
                                                                     delete next[c.phone];
                                                                     localStorage.setItem('pos_customer_db', JSON.stringify(next));
                                                                     return next;
                                                                  });
                                                                 toast.success("Customer profile deleted");
                                                              } else {
                                                                 toast.error("Failed to delete customer from database.");
                                                              }
                                                           } catch (err) {
                                                              console.error("Error deleting customer:", err);
                                                              toast.error("Error deleting customer: " + (err.response?.data?.error || err.message));
                                                           }
                                                        }
                                                     }}

